func farey(n) {
 
    var seq = [0]
    var (a,b,c,d) = (0,1,1,n)
 
    while (c <= n) {
        var k = (n+b)//d
        (a,b,c,d) = (c, d, k*c - a, k*d - b)
        seq << a/b
    }
 
    return seq
}
 
